export class TestCase{failiures=[];warnings=[];successes=0;activeTestFn="";constructor(){return this.test()}test(){for(const t of Object.getOwnPropertyNames(Object.getPrototypeOf(this)))if(t.match(/^(hf)|(ef)/i)&&this[t]&&"function"==typeof this[t]){this.activeTestFn=t;try{this[t]()}catch(t){this.fail(t)}}console.log(JSON.stringify({failiures:this.failiures,successes:this.successes,warnings:this.warnings}))}fail(t="UNKNOWN - If invoking AkriTestCase.fail yourself, always add a message"){this.failiures.push(`${this.activeTestFn}: ${new Error(t)?.stack}`)}ok(){this.successes++}assertEquals(t,s){try{if(t!==s)return this.fail(`Failed to assert that ${t} equals ${s}`)}catch(t){return this.fail(t)}return this.ok()}assertTrue(t){return this.assertEquals(t,!0)}assertFalse(t){return this.assertEquals(t,!1)}assertThrows(t,s=null){"function"!=typeof t&&this.fail(funcName,'Argument "fn" must be a function');let e=!1;try{t()}catch(t){if(e=!0,null!==s&&t!==s)return this.fail(`Failed to assert that exception '${t}' matches expected exception '${s}'`)}finally{return e?this.ok():this.fail("Failed to assert that this test throws an exception")}}}